{
  "findings": [
    {
      "check_id": "CKV_AWS_103",
      "title": "Lambda permission allows invocation from any API Gateway stage/account without source ARN restriction",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "HIGH",
      "explanation": "The resource lacks a 'source_arn' argument, meaning the Lambda function can be invoked by ANY API Gateway endpoint in the account (or potentially cross-account if combined with other misconfigs), rather than being restricted to the specific intended API Gateway resource."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  # TODO: Replace with the actual ARN of the specific API Gateway resource invoking this Lambda\n  # Example: \"arn:aws:execute-api:${var.aws_region}:${data.aws_caller_identity.current.account_id}:${aws_apigatewayv2_api.example.id}/*/${aws_apigatewayv2_stage.example.name}/POST/endpoint\"\n  source_arn    = \"arn:aws:execute-api:*:*:*\"\n}",
  "fix_summary": "Added the 'source_arn' attribute to restrict which API Gateway resources can invoke the Lambda. Note: The value provided is a placeholder pattern; you must replace it with the specific ARN of your API Gateway to enforce least privilege effectively."
}
